CustomField.formula:
IF( OR( ISPICKVAL(Program_Site_Track__c, "FOC"), ISPICKVAL(Program_Site_Track__c, "CCP"), ISPICKVAL(Program_Site_Track__c, "CAP"), ISPICKVAL(Program_Site_Track__c, "CVI"), ISPICKVAL(Program_Site_Track__c, "WDC"), ISPICKVAL(Program_Site_Track__c, "Work First"), ISPICKVAL(Program_Site_Track__c, "XCH") ), /* Verifying Portal is FOC, CAP, CCP, WDC, CVI, Work First or XCH */ IF( NOT(ISNULL(Advancement_Start_Date__c)), "Advancement", /* If Advancement Start Date isn't Null, setting Program Stage to Advancement */ IF( AND( NOT(ISNULL(Start_Date_of_First_Placement__c)), ISNULL(Most_Recent_Employment_End_Date__c), Employment_Status__c <> "Short-Term"
),
"Retention", /* If Start Date of First Placement isn't Null, setting Program Stage to Retention */ IF( AND( TODAY() > (DATEVALUE(TEXT(Scheduled_Program_Start_Date__c)) + 25), OR( ISBLANK(Inactive_Date__c), Inactive_Date__c > (DATEVALUE(TEXT(Scheduled_Program_Start_Date__c)) + 25) ), ISPICKVAL(Accepted__c, "Yes") ), "Leadership Development", /* If conditions match, setting Program Stage to Leadership Development */ IF( AND( TODAY() >= DATEVALUE(TEXT(Scheduled_Program_Start_Date__c)), ISPICKVAL(Accepted__c, "Yes"), OR( ISBLANK(Inactive_Date__c), Inactive_Date__c >= DATEVALUE(TEXT(Scheduled_Program_Start_Date__c)) ) ), "Transformations", /* If today is greater than Program Start Date, set Program Stage to Transformations */ IF( ISPICKVAL(Accepted__c, "Yes"), "Accepted", "Referred" ) /* If Accepted = Yes, set Program Stage to Accepted; otherwise, Referred */ ) ) ) ), NULL )
